<template><section><span class="page-kicker">My account</span><h1 class="page-title">My registered details</h1><StatusMessage :message="error" error retry @retry="load"/><p v-if="loading" role="status">Loading profile...</p><div v-else-if="profile" class="panel"><h2>{{ profile.fullName }}</h2><dl><dt>Mobile</dt><dd>{{ profile.mobileNumber }}</dd><dt>Email</dt><dd>{{ profile.email || 'Not provided' }}</dd><dt>Status</dt><dd>{{ profile.status }}</dd></dl><p>Contact your society administrator to change registered details or ownership.</p><router-link :to="'/members/'+profile.memberId+'/memberships'">My membership history</router-link></div><p v-else-if="!error">Your login account is not linked to a registered person.</p></section></template>
<script>
import {api,errorMessage} from '../services/api';import StatusMessage from '../components/StatusMessage.vue';
export default {components:{StatusMessage},data:()=>({profile:null,error:'',loading:false}),created(){this.load();},methods:{async load(){this.loading=true;this.error='';try{const id=this.$store.state.session.user.memberId;if(id)this.profile=await api.get('members',id);}catch(e){this.error=errorMessage(e);}finally{this.loading=false;}}}};
</script>
